describe("TradeWarRoom — requests and identity", () => {
  it("asks the backend the exact question, in the selected league and mode", async () => {
    await renderWith(CONSOLIDATION);
    const [url, init] = globalThis.fetch.mock.calls[0];
    expect(url).toBe("/api/trade/analyze");
    const body = JSON.parse(init.body);
    expect(body).toMatchObject({
      leagueKey: "main",
      teamName: "Us",
      playersIn: ["WR Buf Star"],
      playersOut: ["WR Kc", "WR Phi"],
      useTeamContext: true,
    });
  });

  it("the mode control asks the page to change mode", async () => {
    const onChange = vi.fn();
    await renderWith(CONSOLIDATION, { onTeamContextChange: onChange });
    fireEvent.click(screen.getByRole("radio", { name: "Asset only" }));
    expect(onChange).toHaveBeenCalledWith(false);
  });

  it("refuses an answer for the other mode", async () => {
    globalThis.fetch = vi.fn(async () => ok(ASSET_ONLY)); // asset-only answer...
    render(<TradeWarRoom request={req(CONSOLIDATION)} leagueKey="main" useTeamContext />); // ...to a team question
    await settle();
    expect(screen.getByTestId("war-room-error")).toHaveTextContent(
      /the server's answer did not match this trade/,
    );
    expect(screen.queryByTestId("decision-headline")).toBeNull();
  });

  it("a late answer to an earlier trade never publishes", async () => {
    const first = deferred();
    globalThis.fetch = vi
      .fn()
      .mockImplementationOnce(() => first.promise)
      .mockResolvedValueOnce(ok(FORCED));
    const view = render(
      <TradeWarRoom request={req(CONSOLIDATION)} leagueKey="main" useTeamContext />,
    );
    await settle();
    view.rerender(<TradeWarRoom request={req(FORCED)} leagueKey="main" useTeamContext />);
    await settle();
    expect(screen.getByTestId("war-room-roster-fit")).toHaveTextContent(/cut Ghost Player/);
    await act(async () => first.resolve(ok(CONSOLIDATION)));
    expect(screen.getByTestId("war-room-roster-fit")).toHaveTextContent(/cut Ghost Player/);
    expect(screen.queryByText("The trade fits. No player cut needed.")).toBeNull();
  });

  it("a change invalidates the request in flight at once, before the debounce fires", async () => {
    const first = deferred();
    globalThis.fetch = vi
      .fn()
      .mockImplementationOnce(() => first.promise)
      .mockResolvedValueOnce(ok(FORCED));
    const view = render(
      <TradeWarRoom request={req(CONSOLIDATION)} leagueKey="main" useTeamContext />,
    );
    await settle(); // the first request has left
    view.rerender(<TradeWarRoom request={req(FORCED)} leagueKey="main" useTeamContext />);
    // The new question is still inside its debounce: the old one is already aborted...
    expect(globalThis.fetch.mock.calls[0][1].signal.aborted).toBe(true);
    // ...so its answer, landing now, is ignored.
    await act(async () => first.resolve(ok(CONSOLIDATION)));
    expect(screen.queryByTestId("decision-headline")).toBeNull();
    expect(screen.getByText("Analyzing this trade…")).toBeInTheDocument();
    await settle();
    expect(screen.getByTestId("decision-headline")).toHaveTextContent(
      FORCED.analysis.decision.headlineText,
    );
  });

  it("a changed trade never shows the previous trade's answer while it updates", async () => {
    const { rerender } = await renderWith(CONSOLIDATION);
    expect(screen.getByTestId("decision-headline")).toBeInTheDocument();
    globalThis.fetch = vi.fn(() => new Promise(() => {}));
    rerender(<TradeWarRoom request={req(FORCED)} leagueKey="main" useTeamContext />);
    await act(async () => {});
    expect(screen.queryByTestId("decision-headline")).toBeNull();
    expect(screen.getByText("Analyzing this trade…")).toBeInTheDocument();
    expect(document.querySelector('[data-war-room="loading"]')).not.toBeNull();
  });

  it("with the mode changed, the previous verdict is blanked", async () => {
    const { rerender } = await renderWith(CONSOLIDATION);
    globalThis.fetch = vi.fn(() => new Promise(() => {}));
    rerender(<TradeWarRoom request={req(CONSOLIDATION)} leagueKey="main" useTeamContext={false} />);
    await act(async () => {});
    expect(screen.getByText("Analyzing this trade…")).toBeInTheDocument();
    expect(screen.queryByTestId("decision-headline")).toBeNull();
  });
});

describe("TradeWarRoom — loading, failure and limits (Part 4)", () => {
  const summary = valueSummaryFromSideTotals(
    [
      { raw: 5848, adjustment: 0, adjusted: 5848 },
      { raw: 4654, adjustment: 0, adjusted: 4654 },
    ],
    0,
  );

  it("shows the calculator's trade value at once — never a provisional YES / NO", async () => {
    globalThis.fetch = vi.fn(() => new Promise(() => {}));
    const request = req(AJ_BROWN);
    const before = structuredClone(request);
    render(
      <TradeWarRoom request={request} leagueKey="main" useTeamContext valueSummary={summary} />,
    );
    await settle();
    expect(screen.getByTestId("war-room-trade-value")).toHaveTextContent(
      tradeValueSummary(summary).sentence,
    );
    expect(row("market")).toHaveTextContent(/while the personalized analysis finishes/);
    expect(within(row("roster")).getByText("Calculating…")).toBeInTheDocument();
    expect(within(row("feasibility")).getByText("Checking…")).toBeInTheDocument();
    expect(screen.queryByTestId("decision-headline")).toBeNull();
    expect(screen.queryByText(/MAKE THE TRADE|TOO CLOSE|NOT ENOUGH EVIDENCE/)).toBeNull();
    // The trade itself is untouched while it loads.
    expect(request).toEqual(before);
  });

  it("replaces the summary with the analysis's own trade value when it arrives", async () => {
    globalThis.fetch = vi.fn(async () => ok(CONSOLIDATION));
    render(
      <TradeWarRoom
        request={req(CONSOLIDATION)}
        leagueKey="main"
        useTeamContext
        valueSummary={summary}
      />,
    );
    await settle();
    expect(screen.getByTestId("war-room-trade-value")).toHaveTextContent(
      tradeValueSummary(CONSOLIDATION.analysis.lenses.market.detail).sentence,
    );
    expect(row("market")).not.toHaveTextContent(/personalized analysis/);
  });

  it("says how long it has been working after a few seconds, without a live region", async () => {
    globalThis.fetch = vi.fn(() => new Promise(() => {}));
    render(<TradeWarRoom request={req(AJ_BROWN)} leagueKey="main" useTeamContext />);
    await settle();
    expect(screen.queryByTestId("war-room-slow")).toBeNull();
    await settle(SLOW_NOTICE_MS + 1000);
    expect(screen.getByTestId("war-room-slow")).toHaveTextContent(/seconds so far/);
    expect(screen.queryByRole("status")).toBeNull();
  });

  it("is bounded: a request that never answers times out honestly, and Retry re-asks", async () => {
    globalThis.fetch = hangingFetch();
    render(
      <TradeWarRoom
        request={req(AJ_BROWN)}
        leagueKey="main"
        useTeamContext
        valueSummary={summary}
      />,
    );
    await settle();
    await settle(ANALYZE_TIMEOUT_MS + 10);
    expect(screen.getByTestId("war-room-error")).toHaveTextContent(/it took too long to finish/);
    expect(screen.queryByText("Analyzing this trade…")).toBeNull();
    // Completed results stay: the trade value is still shown.
    expect(screen.getByTestId("war-room-trade-value")).toHaveTextContent(
      tradeValueSummary(summary).sentence,
    );
    globalThis.fetch.mockImplementation(async () => ok(AJ_BROWN));
    fireEvent.click(screen.getByRole("button", { name: "Retry" }));
    await settle();
    expect(screen.getByTestId("decision-headline")).toHaveTextContent(
      AJ_BROWN.analysis.decision.headlineText,
    );
    const bodies = globalThis.fetch.mock.calls.map((c) => c[1].body);
    expect(bodies[1]).toBe(bodies[0]);
  });

  it("a server error keeps the trade value, explains, and offers Retry", async () => {
    globalThis.fetch = vi.fn(async () => ok({ error: "data_not_ready" }, 503));
    render(
      <TradeWarRoom
        request={req(AJ_BROWN)}
        leagueKey="main"
        useTeamContext
        valueSummary={summary}
      />,
    );
    await settle();
    expect(screen.getByTestId("war-room-error")).toHaveTextContent(
      /this league's data is still loading on the server/,
    );
    expect(row("market")).toHaveTextContent(/did not finish/);
    expect(
      within(row("roster")).getByText(/Unavailable — the analysis did not finish/),
    ).toBeTruthy();
    expect(screen.getByRole("button", { name: "Retry" })).toBeInTheDocument();
  });

  it("an unavailable section is explained while the completed ones render", async () => {
    const p = structuredClone(CONSOLIDATION);
    p.analysis.lenses.roster = {
      available: false,
      unavailableReason: "projection_basis_no_projection_snapshot",
      detail: {},
    };
    await renderWith(p);
    expect(
      within(row("roster")).getByText("No league-scored projection snapshot yet"),
    ).toBeTruthy();
    expect(screen.getByTestId("decision-headline")).toBeInTheDocument();
    expect(screen.getByTestId("war-room-trade-value")).toBeInTheDocument();
    expect(screen.getByTestId("war-room-roster-fit")).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "Lineup impact, player by player" })).toBeNull();
  });

  it("a 3+-team trade gets an explanation, never a fabricated YES / NO", async () => {
    globalThis.fetch = vi.fn();
    const onDecision = vi.fn();
    render(<TradeWarRoom request={null} sideCount={3} teamName="Us" onDecision={onDecision} />);
    await settle();
    expect(screen.getByTestId("war-room-multi-team-limit")).toHaveTextContent(
      /No YES \/ NO is given for this 3-team trade/,
    );
    expect(screen.queryByTestId("decision-headline")).toBeNull();
    expect(globalThis.fetch).not.toHaveBeenCalled();
    expect(onDecision).toHaveBeenLastCalledWith({ status: "multi", decision: null });
  });
});

